      hu: "A fehér márványból épült iszlám építészeti remekmű hatalmas kupoláival és finom díszítéseivel varázsolja el a nézőt.",
      ro: "Această capodoperă a arhitecturii islamice din marmură albă impresionează cu domurile sale uriașe și detaliile fine.",
      en: "This magnificent masterpiece of Islamic architecture in white marble impresses with massive domes and intricate details.",
      es: "Esta magnífica obra maestra de la arquitectura islámica de mármol blanco impresiona con cúpulas gigantes y detalles refinados.",
