      en: ["Opened to the public on February 22, 2022", "Unique torus shape designed without internal columns", "Facade made of 1,024 individual steel panels", "Features Arabic calligraphy of visionary quotes", "Illuminated by 14 kilometers of LED light strips", "The museum spans seven floors of exhibitions"],
