      ro: ["Costurile de construcție au fost de 3 miliarde USD", "Dispune de un număr total de 114 cupole", "S-au folosit 6.000 m² de foiță de aur de 22k", "Plaja privată are o lungime de 1,3 kilometri", "Hotelul a fost inaugurat oficial în anul 2005", "Lățimea cupolei centrale este de 42 de metri"],
      en: ["Construction costs reached 3 billion USD", "Features a total of 114 architectural domes", "6,000 sqm of gold leaf used for interior decor", "The private sandy beach is 1.3 kilometers long", "Officially opened to guests in 2005", "The massive central dome is 42 meters wide"],
      es: ["Inaugurado: 2005", "Número de habitaciones: 394", "Longitud de la playa privada: 1,3 km", "Coste de construcción: 3.000 millones de USD", "Restaurantes: 14", "Plazas de marina: 50"],
      pt: ["Inaugurado: 2005", "Número de quartos: 394", "Comprimento da praia privada: 1,3 km", "Custo de construção: 3 mil milhões de USD", "Restaurantes: 14", "Lugares de marina: 50"],
      fr: ["Inauguré : 2005", "Nombre de chambres : 394", "Longueur de la plage privée : 1,3 km", "Coût de construction : 3 milliards d'USD", "Restaurants : 14", "Places de marina : 50"],
