      en: ["The neighborhood originally dates back to the 1890s.", "The buildings are famous for their wind towers (barjeels) used for ventilation.", "Most houses were built using coral stone, gypsum, and sandstone.", "Prince Charles intervened in 1989 to save the area from scheduled demolition.", "It is home to the Sheikh Mohammed Centre for Cultural Understanding.", "The district is situated directly along the banks of the Dubai Creek in Bur Dubai."],
