      pt: ["O bairro foi construído entre 1900 e 1920.", "A restauração começou em 1980.", "Compreende cerca de 50 casas tradicionais.", "As torres de vento atingem até 15 metros de altura.", "O forte de Al Fahidi foi construído em 1799.", "O bairro está situado no Dubai Creek."],
      fr: ["Le quartier a été construit entre 1900 et 1920.", "La restauration a commencé en 1980.", "Il comprend environ 50 maisons traditionnelles.", "Les tours à vent atteignent jusqu'à 15 mètres de haut.", "Le fort d'Al Fahidi a été construit en 1799.", "Le quartier est situé au bord du Dubai Creek."],
